begin;create extension if not exists pgtap with schema extensions;select no_plan();
insert into auth.users(instance_id,id,aud,role,email,encrypted_password,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at)values('00000000-0000-0000-0000-000000000000','a0000000-0000-0000-0000-000000000001','authenticated','authenticated','lease-a@example.test','',now(),'{}','{}',now(),now()),('00000000-0000-0000-0000-000000000000','a0000000-0000-0000-0000-000000000002','authenticated','authenticated','lease-b@example.test','',now(),'{}','{}',now(),now());
insert into public.organizations(id,public_id,name)values('a1000000-0000-0000-0000-000000000001','org_leaseaaaaaaaaaaa','Lease A'),('a1000000-0000-0000-0000-000000000002','org_leasebbbbbbbbbbb','Lease B');
insert into public.organization_memberships(id,organization_id,user_id,role,status)values('a2000000-0000-0000-0000-000000000001','a1000000-0000-0000-0000-000000000001','a0000000-0000-0000-0000-000000000001','owner','active'),('a2000000-0000-0000-0000-000000000002','a1000000-0000-0000-0000-000000000002','a0000000-0000-0000-0000-000000000002','owner','active');
insert into public.contacts(id,organization_id,created_by_membership_id,assigned_membership_id,first_name,last_name,primary_email,source,lifecycle_status,marketing_email_status)values('a3000000-0000-0000-0000-000000000001','a1000000-0000-0000-0000-000000000001','a2000000-0000-0000-0000-000000000001','a2000000-0000-0000-0000-000000000001','Lease','Recipient','lease@example.test','Lease','nurture','opted-in');
