insert into public.contact_lists(organization_id,created_by_membership_id,name)values('a1000000-0000-0000-0000-000000000001','a2000000-0000-0000-0000-000000000001','Lease list');insert into public.contact_list_memberships(organization_id,list_id,contact_id,added_by_membership_id)values('a1000000-0000-0000-0000-000000000001',(select id from public.contact_lists where name='Lease list'),'a3000000-0000-0000-0000-000000000001','a2000000-0000-0000-0000-000000000001');

reset role;
update public.contacts set preferred_name='Preferred' where id='a3000000-0000-0000-0000-000000000001';
insert into public.marketing_campaigns(public_id,organization_id,created_by_membership_id,name,subject,sender_name,reply_to,audience_type,audience_public_id,status,content_version,content,branding_snapshot)values('camp_studio001ctest','a1000000-0000-0000-0000-000000000001','a2000000-0000-0000-0000-000000000001','Studio campaign','Hello','Alex','alex@example.test','list',(select public_id from public.contact_lists where name='Lease list'),'draft',2,'{"version":2,"type":"email","theme":{"fontFamily":"arial","fontSize":16,"textColor":"#172033","accentColor":"#2563EB"},"document":{"type":"doc","content":[{"type":"paragraph","attrs":{"textAlign":"left"},"content":[{"type":"text","text":"Hi "},{"type":"mergeField","attrs":{"field":"preferred_name"}}]}]}}','{"version":1,"company":"Synthetic company","website":"","postalAddress":"100 Synthetic Lane, Example City","primaryColor":"#172033","accentColor":"#2563EB","font":"arial","logo":null,"headshot":null,"name":"Alex","title":"Consultant","email":"alex@example.test","phone":"","linkedIn":"","scheduling":""}');
create temporary table proof(stage uuid,send text,recipient text,test text);insert into proof default values;grant all on proof to authenticated,service_role;
insert into public.studio_media_assets(public_id,organization_id,creator_membership_id,source_mime,output_mime,width,height,byte_size,source_byte_size,checksum,source_checksum,source_path,delivery_path,thumbnail_path)
select 'asset_'||repeat('c',32),'a1000000-0000-0000-0000-000000000001','a2000000-0000-0000-0000-000000000001','image/png','image/png',100,100,100,100,repeat('a',64),repeat('b',64),'a1000000-0000-0000-0000-000000000001/asset_'||repeat('c',32)||'/1/original','a1000000-0000-0000-0000-000000000001/asset_'||repeat('c',32)||'/1/email.png','a1000000-0000-0000-0000-000000000001/asset_'||repeat('c',32)||'/1/thumb.png';
set local role authenticated;
select is((public.review_studio_campaign('camp_studio001ctest')->>'eligible')::int,1,'V2 review resolves exactly one eligible contact');
select is((public.review_studio_campaign('camp_studio001ctest')->>'eligible')::bigint,(select eligible_count from public.resolve_campaign_audience('list',(select public_id from public.contact_lists where name='Lease list')) limit 1),'review count equals existing audience preview');
select throws_ok($$select public.stage_studio_campaign('camp_studio001ctest','a2000000-0000-0000-0000-000000000001',now(),repeat('a',64),'https://evil.test','https://evil.test')$$,'42501',null,'client cannot forge trusted render origins or stages');
select throws_ok($$select public.confirm_campaign_send('camp_studio001ctest','v1-bypass-key-0001',false)$$,'42501',null,'V1 RPC cannot bypass V2 confirmation');
select set_config('request.jwt.claim.sub','a0000000-0000-0000-0000-000000000002',true);
select throws_ok($$select public.review_studio_campaign('camp_studio001ctest')$$,'42501',null,'cross tenant review blocked');
reset role;
select throws_ok($$select public.stage_studio_campaign('camp_studio001ctest','a2000000-0000-0000-0000-000000000002',now(),repeat('a',64),'https://demo.example.test','https://media.example.test')$$,'42501',null,'wrong membership cannot stage a campaign');
update public.organization_memberships set status='suspended' where id='a2000000-0000-0000-0000-000000000001';
select throws_ok($$select public.stage_studio_campaign('camp_studio001ctest','a2000000-0000-0000-0000-000000000001',now(),repeat('a',64),'https://demo.example.test','https://media.example.test')$$,'42501',null,'inactive membership cannot stage');
update public.organization_memberships set status='active' where id='a2000000-0000-0000-0000-000000000001';
select throws_ok($$select public.stage_studio_campaign('camp_studio001ctest','a2000000-0000-0000-0000-000000000001',now()-interval '1 day',repeat('a',64),'https://demo.example.test','https://media.example.test')$$,'40001',null,'stale revision cannot stage');
update public.marketing_campaigns set branding_snapshot=jsonb_set(branding_snapshot,'{postalAddress}','""') where public_id='camp_studio001ctest';
select throws_ok($$select public.stage_studio_campaign('camp_studio001ctest','a2000000-0000-0000-0000-000000000001',(select updated_at from public.marketing_campaigns where public_id='camp_studio001ctest'),repeat('a',64),'https://demo.example.test','https://media.example.test')$$,'P0001',null,'missing postal address blocks staging');
update public.marketing_campaigns set branding_snapshot='{"version":1,"company":"Synthetic company","website":"","postalAddress":"100 Synthetic Lane, Example City","primaryColor":"#172033","accentColor":"#2563EB","font":"arial","logo":null,"headshot":null,"name":"Alex","title":"Consultant","email":"alex@example.test","phone":"","linkedIn":"","scheduling":""}' where public_id='camp_studio001ctest';
select set_config('request.jwt.claim.sub','a0000000-0000-0000-0000-000000000001',true);
update public.marketing_campaigns set branding_snapshot=jsonb_set(branding_snapshot,'{logo}',to_jsonb('asset_'||repeat('c',32))) where public_id='camp_studio001ctest';
update public.studio_media_assets set status='archived' where public_id='asset_'||repeat('c',32);
select throws_ok($$select public.stage_studio_campaign('camp_studio001ctest','a2000000-0000-0000-0000-000000000001',(select updated_at from public.marketing_campaigns where public_id='camp_studio001ctest'),repeat('a',64),'https://demo.example.test','https://media.example.test')$$,'42501',null,'unpublished media blocks staging');
update public.studio_media_assets set status='ready' where public_id='asset_'||repeat('c',32);
update proof set stage=(public.stage_studio_campaign('camp_studio001ctest','a2000000-0000-0000-0000-000000000001',(select updated_at from public.marketing_campaigns where public_id='camp_studio001ctest'),public.review_studio_campaign('camp_studio001ctest')->>'fingerprint','https://demo.example.test','https://media.example.test')->>'stageId')::uuid;
select throws_ok($$update private.studio_send_stages set source='{}'$$,'42501',null,'staged source is immutable');
set local role authenticated;
select set_config('request.jwt.claim.sub','a0000000-0000-0000-0000-000000000002',true);
select throws_ok($$select public.confirm_studio_campaign('camp_studio001ctest',(select stage from proof),'studio-confirm-key-0001',false)$$,'42501',null,'cross tenant confirmation blocked');
select set_config('request.jwt.claim.sub','a0000000-0000-0000-0000-000000000001',true);
select throws_ok($$select public.confirm_studio_campaign('wrong-campaign',(select stage from proof),'studio-confirm-key-0001',false)$$,'42501',null,'review cannot confirm a different campaign');
reset role;
update public.contacts set preferred_name='Changed' where id='a3000000-0000-0000-0000-000000000001';
set local role authenticated;
select throws_ok($$select public.confirm_studio_campaign('camp_studio001ctest',(select stage from proof),'studio-confirm-key-0001',false)$$,'40001',null,'personalization change invalidates audience review');
reset role;update public.contacts set preferred_name='Preferred' where id='a3000000-0000-0000-0000-000000000001';
update public.marketing_campaigns set subject='Changed' where public_id='camp_studio001ctest';
set local role authenticated;
select throws_ok($$select public.confirm_studio_campaign('camp_studio001ctest',(select stage from proof),'studio-confirm-key-0001',false)$$,'40001',null,'draft change invalidates confirmation');
reset role;
update proof set stage=(public.stage_studio_campaign('camp_studio001ctest','a2000000-0000-0000-0000-000000000001',(select updated_at from public.marketing_campaigns where public_id='camp_studio001ctest'),public.review_studio_campaign('camp_studio001ctest')->>'fingerprint','https://demo.example.test','https://media.example.test')->>'stageId')::uuid;
-- Isolated test audit: no normal run, recipient or consent mutation.
update public.studio_media_assets set status='archived' where public_id='asset_'||repeat('c',32);
select throws_ok($$select public.confirm_studio_campaign('camp_studio001ctest',(select stage from proof),'studio-confirm-key-0001',false)$$,'P0001',null,'media publication change blocks confirmation');
update public.studio_media_assets set status='ready' where public_id='asset_'||repeat('c',32);
select throws_ok($$select public.confirm_studio_campaign('camp_studio001ctest',(select stage from proof),'studio-confirm-key-0001',true)$$,'22023',null,'caller cannot mislabel an external V2 send as simulated');
update public.organizations set status='suspended' where id='a1000000-0000-0000-0000-000000000001';
select throws_ok($$select public.prepare_studio_test((select stage from proof),'a2000000-0000-0000-0000-000000000001','studio-test-key-0001','{}',repeat('c',64))$$,'42501',null,'suspended organization cannot send a staged test');
update public.organizations set status='active' where id='a1000000-0000-0000-0000-000000000001';
update proof set test=public.prepare_studio_test((select stage from proof),'a2000000-0000-0000-0000-000000000001','studio-test-key-0001','{"to":"approved@real-domain.org","senderName":"Alex","replyTo":"alex@example.test","subject":"[TEST] Hello","html":"<p>Frozen test</p>","text":"Frozen test"}',repeat('c',64))->>'id';
select is((select count(*) from public.marketing_send_runs),0::bigint,'test send creates no normal campaign run');
select is((select count(*) from public.marketing_send_recipients),0::bigint,'test send creates no campaign recipient');
select is((select marketing_email_status::text from public.contacts where id='a3000000-0000-0000-0000-000000000001'),'opted-in','test preparation preserves consent');
select ok(public.claim_studio_test((select test from proof)) is not null,'test payload can be claimed once');
select ok(public.claim_studio_test((select test from proof)) is null,'second test claim cannot duplicate send');
select ok(not public.record_marketing_provider_event('mock-test-message','resend','studio-test-early','accepted',now()),'early verified webhook waits for provider response');
select is((select count(*) from private.studio_pending_provider_events),1::bigint,'early event retained durably');
select lives_ok($$select public.complete_studio_test((select test from proof),'mock-test-message',null)$$,'test acceptance auditable');
select is((select count(*) from private.studio_pending_provider_events),0::bigint,'response persistence reconciles early event');
select ok(public.record_marketing_provider_event('mock-test-message','resend','studio-test-delivered','delivered',now()),'test webhook uses existing reconciliation entry point');
select ok(not public.record_marketing_provider_event('mock-test-message','resend','studio-test-delivered','delivered',now()),'test webhook replay deduplicates');
select ok(public.record_marketing_provider_event('mock-test-message','resend','studio-test-complaint','complaint',now()),'test complaint remains auditable');
select is((select count(*) from private.studio_test_events),3::bigint,'test provider events persist separately');
select is((select count(*) from public.marketing_delivery_events),0::bigint,'test events never create campaign analytics');
select throws_ok($$update private.studio_test_payloads set payload='{}'$$,'42501',null,'test HTML/text immutable');
select ok(public.unsubscribe_studio_test(repeat('c',64)),'test unsubscribe token resolves');
select ok(public.unsubscribe_studio_test(repeat('c',64)),'test unsubscribe repeats safely');
select is((select marketing_email_status::text from public.contacts where id='a3000000-0000-0000-0000-000000000001'),'opted-in','test unsubscribe never changes contact consent');
set local role authenticated;
select throws_ok($$select * from private.studio_test_payloads$$,'42501',null,'normal clients cannot read test payload tokens');
select throws_ok($$select * from private.studio_test_events$$,'42501',null,'test provider evidence remains private');
reset role;
-- Force a contact edit between the fingerprint check and recipient insertion.
-- This models the READ COMMITTED interleaving without timing-dependent sleeps.
create function pg_temp.edit_after_audience_check() returns trigger language plpgsql as $$begin
 update public.contacts set preferred_name='After fingerprint' where id='a3000000-0000-0000-0000-000000000001';return new;end $$;
create trigger studio_test_interleaving after insert on public.marketing_send_runs for each row execute function pg_temp.edit_after_audience_check();
set local role authenticated;
update proof set send=(public.confirm_studio_campaign('camp_studio001ctest',(select stage from proof),'studio-confirm-key-0001',false)).public_id;
select is((select status::text from public.marketing_campaigns where public_id='camp_studio001ctest'),'sending','explicit confirmation freezes campaign');
select is((public.confirm_studio_campaign('camp_studio001ctest',(select stage from proof),'studio-confirm-key-0001',false)).public_id,(select send from proof),'confirmation replay returns same run');
select is((select personalization->>'preferredName' from public.marketing_send_recipients),'Preferred','V2 snapshots actual preferred name');
select is((select studio_snapshot->>'rendererVersion' from public.marketing_send_runs),'studio-001c-1','renderer version frozen');
reset role;
select throws_ok($$update public.marketing_campaigns set subject='Oops' where public_id='camp_studio001ctest'$$,'42501',null,'confirmed campaign cannot be edited');
select throws_ok($$update public.marketing_send_runs set subject='Oops'$$,'42501',null,'confirmed send cannot be edited');
select throws_ok($$update public.marketing_send_recipients set normalized_email='other@real-domain.org'$$,'42501',null,'recipient address cannot be changed');
select throws_ok($$update public.marketing_send_recipients set personalization='{}'$$,'42501',null,'recipient personalization cannot be changed');
select set_config('request.jwt.claims','{"role":"service_role"}',true);set local role service_role;
select is((select count(*) from public.claim_campaign_recipients((select send from proof),1,'a4000000-0000-0000-0000-000000000001')),1::bigint,'existing worker claims V2 recipient');
select is((select count(*) from public.claim_campaign_recipients((select send from proof),1,'a4000000-0000-0000-0000-000000000002')),0::bigint,'duplicate worker cannot claim active lease');
reset role;update proof set recipient=(select public_id from public.marketing_send_recipients);
set local role service_role;
select ok(public.studio_recipient_payload((select recipient from proof),'a4000000-0000-0000-0000-000000000001') is null,'first claim has no rendered artifact yet');
select throws_ok($$select public.studio_recipient_payload((select recipient from proof),'a4000000-0000-0000-0000-000000000002')$$,'42501',null,'wrong claim cannot read recipient payload');
select lives_ok($$select public.studio_recipient_payload((select recipient from proof),'a4000000-0000-0000-0000-000000000001',jsonb_build_object('to','lease@example.test','deliveryKey',(select recipient from proof),'senderName','Alex','replyTo','alex@example.test','html','<p>Frozen recipient</p>','text','Frozen recipient'),repeat('d',64))$$,'HTML and text persist atomically with unsubscribe hash');
reset role;
select is((select payload->>'html' from private.studio_recipient_payloads),'<p>Frozen recipient</p>','HTML artifact preserved');
select is((select payload->>'text' from private.studio_recipient_payloads),'Frozen recipient','independent text artifact preserved');
select throws_ok($$update private.studio_recipient_payloads set payload='{}'$$,'42501',null,'rendered artifact is immutable');
update public.marketing_send_recipients set claimed_at=now()-interval '16 minutes';
set local role service_role;
select is((select count(*) from public.claim_campaign_recipients((select send from proof),1,'a4000000-0000-0000-0000-000000000002')),1::bigint,'stale lease recovers through existing worker');
select is(public.studio_recipient_payload((select recipient from proof),'a4000000-0000-0000-0000-000000000002','{"html":"changed"}',repeat('e',64))->>'html','<p>Frozen recipient</p>','retry reuses exact original payload rather than re-rendering');
select throws_ok($$select public.complete_campaign_recipient((select recipient from proof),'a4000000-0000-0000-0000-000000000001','accepted','stale',null)$$,'42501',null,'stale worker cannot complete');
select lives_ok($$select public.complete_campaign_recipient((select recipient from proof),'a4000000-0000-0000-0000-000000000002','failed',null,'mock-failure')$$,'provider failure recorded as failure');
reset role;
select is((select status::text from public.marketing_send_recipients),'failed','provider failure is never marked delivered');
-- Independently exercise a recovered lease whose delivered webhook arrives
-- before the HTTP acceptance is persisted by the worker.
update public.marketing_send_recipients set status='processing';
select ok(not public.record_marketing_provider_event('mock-campaign-early','resend','studio-campaign-early','delivered',now()),'early campaign webhook retained');
set local role service_role;
select lives_ok($$select public.complete_campaign_recipient((select recipient from proof),'a4000000-0000-0000-0000-000000000002','accepted','mock-campaign-early',null)$$,'worker response reconciles early campaign delivery');
reset role;
select is((select status::text from public.marketing_send_recipients),'delivered','early delivery event remains delivered after acceptance');
select is((select count(*) from private.studio_pending_provider_events),0::bigint,'reconciled campaign event leaves no pending entry');
select ok(public.unsubscribe_marketing(repeat('d',64)),'V2 frozen unsubscribe token resolves through existing consent path');
select is((select marketing_email_status::text from public.contacts where id='a3000000-0000-0000-0000-000000000001'),'opted-out','V2 unsubscribe preserves existing consent behavior');
set local role authenticated;
select throws_ok($$select * from private.studio_recipient_payloads$$,'42501',null,'normal campaign UI cannot read live unsubscribe URLs');
select throws_ok($$select public.studio_recipient_payload((select recipient from proof),'a4000000-0000-0000-0000-000000000002')$$,'42501',null,'private payload RPC restricted to worker');
select * from finish();rollback;
